const SOUND_DATA = {
  "shoot": "data:audio/wav;base64,",
  "hit": "data:audio/wav;base64,",
  "playerHit": "data:audio/wav;base64,",
  "powerup": "data:audio/wav;base64,",
  "ovule": "data:audio/wav;base64,",
  "levelWin": "data:audio/wav;base64,",
  "gameOver": "data:audio/wav;base64,",
  "start": "data:audio/wav;base64,",
  "multiActivate": "data:audio/wav;base64,",
};

function playSound(name) {
  if (!audioCtx) return;
  const src = audioCtx.createBufferSource();
  const url = SOUND_DATA[name];
  if (!url) return;
  audioCtx.decodeAudioData(url.replace('data:audio/wav;base64,', '').split(',')[0].replace(/-/g, '+').replace(/_/g, '/'),
    function(buffer) {
      const source = audioCtx.createBufferSource();
      source.buffer = buffer;
      source.connect(masterGain);
      source.start(0);
    },
    function() {}
  );
}
audioContextReady = true;
